package vn.ticketscenter.config.worker;
import vn.ticketscenter.config.persistence.*;import java.util.*;
public final class OutboxWorker {public interface EmailJob{void send(String eventType,String payload);}private final TransactionManager tx;private final EmailJob email;private final String owner;public OutboxWorker(TransactionManager tx,EmailJob email,String owner){this.tx=tx;this.email=email;this.owner=owner;}public int runOnce(){return tx.execute(DatabasePrincipal.WORKER,em->{List<Object[]> rows=em.createNativeQuery("SELECT TOP 50 id,event_type,payload FROM dbo.tc_outbox WITH (UPDLOCK,READPAST) WHERE (status IN ('PENDING','FAILED') OR (status='PROCESSING' AND lease_until<=SYSUTCDATETIME())) AND event_type<>'EVENT_CANCELLED' AND available_at<=SYSUTCDATETIME() ORDER BY created_at").getResultList();for(Object[]r:rows){UUID id=(UUID)r[0];em.createNativeQuery("UPDATE dbo.tc_outbox SET status='PROCESSING',lease_owner=:o,lease_until=DATEADD(minute,2,SYSUTCDATETIME()),attempts=attempts+1 WHERE id=:id").setParameter("o",owner).setParameter("id",id).executeUpdate();try{email.send((String)r[1],(String)r[2]);em.createNativeQuery("UPDATE dbo.tc_outbox SET status='PUBLISHED',published_at=SYSUTCDATETIME(),lease_owner=NULL,lease_until=NULL WHERE id=:id").setParameter("id",id).executeUpdate();}catch(RuntimeException e){em.createNativeQuery("UPDATE dbo.tc_outbox SET status='FAILED',available_at=DATEADD(minute,5,SYSUTCDATETIME()),lease_owner=NULL,lease_until=NULL WHERE id=:id").setParameter("id",id).executeUpdate();}}return rows.size();});}}
